# python
from openpyxl import load_workbook

def hex_rgb(cell):
    f = cell.fill
    if f and f.fgColor and f.fgColor.type == 'rgb' and f.fgColor.rgb:
        return f.fgColor.rgb[-6:].upper()
    return None

def is_blue(h):
    if not h: return False
    r = int(h[0:2],16); g=int(h[2:4],16); b=int(h[4:6],16)
    return b>200 and r<80 and g<200

path = '/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/65afbc8a-89ca-4ad5-8d62-355bb401f61d.xlsx'
wb = load_workbook(path)
ws = wb.active

map_data = {}
blue_cells = []
for row in ws.iter_rows():
    for c in row:
        coord = c.coordinate
        color = hex_rgb(c)
        map_data[coord] = {'val': c.value, 'color': color}
        if is_blue(color):
            blue_cells.append(coord)

print('Total cells:', len(map_data))
print('Blue count:', len(blue_cells))
print('Sample:', list(map_data.items())[:10])
